#include <stdio.h>

/* freteDaLoja le o peso (kg) e a distancia (km) digitados e imprime o frete
   numa linha so. Cada degrau cobra as DUAS medidas com &&:
     frete 50 -> peso de 5 para cima   E distancia de 100 para cima
     frete 30 -> peso de 5 para cima   E distancia abaixo de 100
     frete 20 -> peso abaixo de 5      E distancia de 100 para cima
     frete 10 -> o resto (o else, sem condicao)
   A leitura ja esta escrita. Falta a cascata. */
void freteDaLoja(void) {
    int peso = 0;
    int distancia = 0;

    scanf("%d %d", &peso, &distancia);

    /* escreva a cascata aqui, no lugar desta linha */
    printf("frete 10\n");
}

