#include <stdio.h>

void freteDaLoja(void) {
    int peso = 0;
    int distancia = 0;

    scanf("%d %d", &peso, &distancia);

    if (peso >= 5 && distancia >= 100) {
        printf("frete 50\n");
    } else if (peso >= 5 && distancia < 100) {
        printf("frete 30\n");
    } else if (peso < 5 && distancia >= 100) {
        printf("frete 20\n");
    } else {
        printf("frete 10\n");
    }
}
